lab.solution:
from threading import Lock, Thread

class ProgressCounter:
    def __init__(self):
        self.value = 0
        self._lock = Lock()

    def add(self, amount):
        with self._lock:
            self.value += amount

counter = ProgressCounter()
def worker():
    for _ in range(100):
        counter.add(1)

workers = [Thread(target=worker) for _ in range(2)]
for thread in workers:
    thread.start()
for thread in workers:
    thread.join()
assert counter.value == 200
print(counter.value)
